ee:variables.ee:set-variable:
%dw 2.0 output application/json
var failedProjectResults = (vars.combinedLineItemResults default []) filter ((item) -> item.overallSyncStatus == "Failure")
--- (vars.failedOpportunitiesList default []) ++ (if (!isEmpty(failedProjectResults))[{ opportunityId: failedProjectResults[0].opportunityId default "", accountId: vars.accountId default "", failureReason: "OPPORTUNITY_PROCESSING_FAILED", processResult: failedProjectResults }] else [] )
